const H = (typeof $helpers !== 'undefined') ? $helpers : this.helpers;

function normUrl(u) {
  try {
    const x = new URL(String(u).trim());
    if (x.protocol !== 'http:' && x.protocol !== 'https:') return null;
    x.hash = '';
    for (const k of [...x.searchParams.keys()]) {
      if (/^(utm_|gclid$|fbclid$|ved$|usg$|sa$)/i.test(k)) x.searchParams.delete(k);
    }
    x.hostname = x.hostname.toLowerCase().replace(/^www\./, '');
    let s = x.toString();
    if (x.pathname.length > 1 && !x.search && s.endsWith('/')) s = s.slice(0, -1);
    return s;
  } catch (e) { return null; }
}

function hostOf(u) {
  try { return new URL(u).hostname.toLowerCase().replace(/^www\./, ''); } catch (e) { return ''; }
}

function platformOf(host) {
  const h = host || '';
  const is = (d) => h === d || h.endsWith('.' + d);
  if (is('t.me') || is('telegram.me')) return 'telegram';
  if (is('scribd.com')) return 'scribd';
  if (is('docero.com.br') || is('docero.net')) return 'docero';
  if (is('passeidireto.com')) return 'passeidireto';
  if (is('4shared.com')) return '4shared';
  if (is('mediafire.com')) return 'mediafire';
  if (is('mercadolivre.com.br') || is('mercadolibre.com')) return 'mercadolivre';
  if (/(^|\.)amazon\./.test(h)) return 'amazon';
  if (is('drive.google.com') || is('docs.google.com')) return 'drive';
  return 'web';
}

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
// Marca cada hallazgo como en_whitelist (tienda oficial, sitio de la autora, redes de lectores).
const out = [];
$input.all().forEach((it, i) => {
  const a = it.json;
  const host = hostOf(a.url);
  const nurl = normUrl(a.url) || a.url;
  const dom = (a.wl || []).find((d) => host === d || host.endsWith('.' + d));
  const oficial = (a.urls_oficiais || []).find((u) => {
    const n = normUrl(u);
    return n && nurl.startsWith(n);
  });
  const siteOficial = a.site_oficial && (host === a.site_oficial || host.endsWith('.' + a.site_oficial));
  const asinHit = a.asin && /(^|\.)amazon\./.test(host) && String(a.url).includes(a.asin);
  let motivo = null;
  if (dom) motivo = 'whitelist dominio ' + dom;
  else if (oficial) motivo = 'URL oficial de la obra';
  else if (siteOficial) motivo = 'sitio de la autora';
  else if (asinHit) motivo = 'ficha oficial de Amazon (ASIN)';
  out.push({
    json: {
      id: a.id, url: a.url, plataforma: a.plataforma, snippet: a.snippet, es_frase: a.es_frase,
      obra_titulo: a.obra_titulo, nome_autoral: a.nome_autoral,
      en_whitelist: !!motivo, wl_motivo: motivo,
    },
    pairedItem: { item: i },
  });
});
return out;

// Entrada (Merge por posición): hallazgo + respuesta de /pagina. Arma el body para Ollama.
const MODELO = 'qwen2.5:14b';   // EDITAR: cualquier modelo que tengas en Ollama (ollama list)
const SYS = [
  'Sos un analista antipiratería de libros. Decidís si una URL ofrece, aloja o vende copias NO autorizadas de un libro.',
  'Respondé SOLO con un objeto JSON, sin texto extra, con estas claves:',
  '"infractor" (true o false), "confianza" (número entre 0 y 1), "tipo" (uno de: pdf_direto, agregador, grupo_telegram, listing, otro), "motivo" (una frase corta en español).',
  'Reglas:',
  '- infractor=true solo si el resultado permite leer o descargar el libro completo, o vende una copia que no es la edición oficial.',
  '- Un archivo PDF/EPUB/MOBI con el título del libro es infractor=true.',
  '- infractor=false si es una reseña, blog, noticia, ficha de una librería oficial, red social de lectores, o si solo menciona el título.',
  '- Si dudás, usá confianza menor a 0.6.',
].join('\n');

return $input.all().map((it, i) => {
  const j = it.json;
  const datos = {
    libro: j.obra_titulo,
    autora: j.nome_autoral,
    url: j.url,
    plataforma: j.plataforma,
    texto_del_resultado: j.snippet || null,
    tipo_de_contenido: j.content_type || null,
    tamano_bytes: j.bytes || null,
    http_status: j.status || null,
    titulo_pagina: j.titulo || null,
    texto_pagina: String(j.texto || '').slice(0, 2000),
  };
  const body = {
    model: MODELO,
    stream: false,
    format: 'json',
    options: { temperature: 0, num_ctx: 4096 },
    messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(datos) }],
  };
  return {
    json: {
      id: j.id, url: j.url, es_frase: j.es_frase, plataforma: j.plataforma, motor: j.motor,
      content_type: j.content_type || null, ollama_body: body,
    },
    pairedItem: { item: i },
  };
});

// Entrada (Merge por posición): item del prompt + respuesta de Ollama (message.content).
// Decide el estado. Con umbral_auto y umbral_rechazo en 1.01 (default) nada se confirma ni se descarta solo:
// todo va a la cola humana. Si Ollama no respondió, el hallazgo queda en 'novo' para reintentarlo.
const cfg = $('Config').first().json.cfg || {};
const umbral = parseFloat(cfg.umbral_auto || '1.01');
// Descarte automático: con 1.01 (default) nada se descarta solo. Un descarte es definitivo (la URL no vuelve a entrar).
const umbralRechazo = parseFloat(cfg.umbral_rechazo || '1.01');
const TIPOS = ['pdf_direto', 'agregador', 'grupo_telegram', 'listing', 'otro'];

return $input.all().map((it, i) => {
  const j = it.json;
  // Ollama caído (timeout, Mac mini dormida, túnel cortado): el hallazgo queda en 'novo' y se reintenta en la próxima corrida.
  if (j.error && !j.message) {
    return { json: { id: j.id, url: j.url, status: 'novo', confianca: null, tipo: null, motivo: null, sin_llm: true }, pairedItem: { item: i } };
  }
  let r = null;
  try {
    let c = (j.message && j.message.content) || '';
    c = String(c).replace(/```json|```/g, '').trim();
    const m = c.match(/\{[\s\S]*\}/);
    r = JSON.parse(m ? m[0] : c);
  } catch (e) { r = null; }

  let infractor = !!r && (r.infractor === true || r.infractor === 'true');
  let conf = r ? parseFloat(r.confianza) : 0;
  if (isNaN(conf)) conf = 0;
  conf = Math.min(1, Math.max(0, conf));
  const tipo = r && TIPOS.includes(r.tipo) ? r.tipo : 'otro';
  let motivo = r ? String(r.motivo || '').slice(0, 300) : 'LLM sin respuesta válida: revisar a mano';

  // Coincidencia de frase exacta del interior del libro: evidencia fuerte (casi cero falsos positivos).
  if (r && j.es_frase && infractor) {
    conf = Math.max(conf, 0.9);
    motivo += ' [coincide frase exacta del libro]';
  }

  let status;
  if (!r) status = 'revisao';
  else if (!infractor && conf >= umbralRechazo) status = 'rejeitado';
  else if (infractor && conf >= umbral) status = 'confirmado';
  else status = 'revisao';

  return { json: { id: j.id, url: j.url, status, confianca: conf, tipo, motivo, sin_llm: false }, pairedItem: { item: i } };
});

// Entrada: salida de "Decidir". Si Ollama no respondió, avisa por Telegram como máximo una vez cada 6 horas
// (el triage corre cada 30 min y los hallazgos quedan en 'novo' hasta que vuelva).
const cfg = $('Config').first().json.cfg || {};
const chat = String(cfg.telegram_admin_chat_id || '').trim();
const items = $input.all().map((i) => i.json);
const fallidos = items.filter((x) => x.sin_llm).length;
if (!chat || !fallidos) return [];
const st = $getWorkflowStaticData('global');
const ahora = Date.now();
if (st.ultimo_aviso_llm && ahora - st.ultimo_aviso_llm < 6 * 3600 * 1000) return [];
st.ultimo_aviso_llm = ahora;
return [{
  json: {
    chat_id: chat,
    texto: `⚠️ <b>Triage</b>: Ollama no respondió para ${fallidos} de ${items.length} hallazgos. `
      + 'Quedan en cola (novo) y se reintentan solos. Revisá que la Mac mini esté despierta y el túnel/Tailscale arriba. '
      + '(Este aviso se repite como máximo cada 6 h.)',
  },
}];
